select case when c.country in ('TH', 'UK') then 'core' else 'other' end as country_group, case when c.age >= 62 then 'high' when c.age >= 40 then 'mid' else 'low' end as age_bucket, avg(o.discount) as avg_discount, sum(case when o.channel = 'mobile' then o.shipping_fee else 0 end) as mobile_shipping_fee from orders o left join customers c on o.customer_id = c.id group by case when c.country in ('TH', 'UK') then 'core' else 'other' end, case when c.age >= 62 then 'high' when c.age >= 40 then 'mid' else 'low' end order by age_bucket, country_group limit 20;
